using System.Diagnostics;
using System.IO;
using System.Text.Json;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace GeMMeElec;

internal static class NewWorkflowTests
{
    private static Editor ParallelWires(int count=4)
    {
        var e=new Editor();e.Change(()=>{for(int i=0;i<count;i++){var a=new Component{Symbol="terminal",X=200+i*100,Y=140,Tag="S"+(i+1)};var b=new Component{Symbol="terminal",X=200+i*100,Y=600,Tag="D"+(i+1)};e.Sheet.Components.AddRange([a,b]);e.Sheet.Wires.Add(new(){From=new(a.Id,"2"),To=new(b.Id,"1"),Number="P"+(i+1)});}});return e;
    }
    private static void Render(Editor e,string path)
    {
        var visual=new DrawingVisual();using(var dc=visual.RenderOpen()){dc.DrawRectangle(Brushes.White,null,new(0,0,e.Sheet.Width,e.Sheet.Height));Drawing.Render(dc,Drawing.Scene(e.Project,e.Sheet));}var image=new RenderTargetBitmap((int)e.Sheet.Width,(int)e.Sheet.Height,96,96,PixelFormats.Pbgra32);image.Render(visual);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));using var file=File.Create(path);encoder.Save(file);
    }
    public static void Run(Action<string,Action> test,Action<bool,string> assert,Action<Action> reject,string dir)
    {
        test("Vidéo : quatre bornes, continuités séparées, une annulation",()=>{
            var e=ParallelWires();string before=e.ExportSnapshot;var strip=e.InsertTerminalLine(new(160,300),new(540,300),"X1");assert(strip.Terminals.Count==4&&e.Sheet.Wires.Count==8,"Quatre insertions");
            foreach(var t in strip.Terminals){var wires=e.Sheet.Wires.Where(w=>w.From.ComponentId==t.ComponentId||w.To.ComponentId==t.ComponentId).ToList();assert(wires.Count==2&&wires[0].Number==wires[1].Number,"Numéro passage");assert(ProjectNavigation.Circuit(e.Project,wires[0].Id).Count==2,"La ligne ne ponte pas les conducteurs");}
            string after=e.ExportSnapshot;e.Undo();assert(e.ExportSnapshot==before,"Undo unique");e.Redo();assert(e.ExportSnapshot==after,"Redo unique");
        });
        test("Vidéo : câble et section, aucun court-circuit, persistance",()=>{
            var e=ParallelWires();e.InsertTerminalLine(new(160,300),new(540,300),"X1");var numbers=e.Sheet.Wires.ToDictionary(w=>w.Id,w=>w.Number);var cable=e.MarkCableLine(new(160,400),new(540,400),"W1",2.5,"H07V-K");assert(e.Sheet.Wires.Count==8&&e.Sheet.Wires.All(w=>numbers[w.Id]==w.Number),"Fils et numéros conservés");assert(e.Sheet.Wires.Count(w=>w.CableId==cable.Id)==4&&e.Sheet.Wires.Where(w=>w.CableId==cable.Id).Select(w=>w.CableCore).Distinct().Count()==4,"Quatre conducteurs");assert(Drawing.Scene(e.Project,e.Sheet).Any(i=>i.Text.Contains("4 × 2,5 mm²")),"Section affichée");
            var loaded=ProjectStore.Deserialize(e.ExportSnapshot);assert(loaded.Cables.Single().SectionMm2==2.5&&loaded.Sheets[0].CableMarkers.Count==1,"Relecture");foreach(var w in e.Sheet.Wires)assert(ProjectNavigation.Circuit(e.Project,w.Id).Count==2,"Aucune liaison électrique par la ligne de câble");Render(e,Path.Combine(dir,"self-test-video.png"));Export.Pdf(e.Project,Path.Combine(dir,"self-test-video.pdf"));
            string after=e.ExportSnapshot;e.Undo();assert(e.Project.Cables.Count==0,"Undo câble");e.Redo();assert(e.ExportSnapshot==after,"Redo câble");
        });
        test("Vidéo : refus de section et numéros de borne dupliqués atomiques",()=>{
            var e=ParallelWires();e.InsertTerminalLine(new(160,300),new(540,300),"X1");var before=e.ExportSnapshot;reject(()=>e.MarkCableLine(new(160,400),new(540,400),"W1",0));assert(e.ExportSnapshot==before,"Section zéro rollback");reject(()=>e.InsertTerminalLine(new(160,450),new(540,450),"X1"));assert(e.ExportSnapshot==before,"Numéro dupliqué rollback");reject(()=>e.MarkCableLine(new(100,400),new(120,400),"W1",1.5));assert(e.ExportSnapshot==before,"Aucun fil rollback");
        });
        test("Insertion : quatre directions et métadonnées indépendantes",()=>{
            foreach(int rotation in new[]{0,90,180,270}){var e=new Editor();var a=e.AddComponent("terminal",400,400);var b=e.AddComponent("terminal",400,700);e.Change(()=>{a.Rotation=rotation;b.Rotation=rotation;var unit=new Vector(-Math.Sin(rotation*Math.PI/180),Math.Cos(rotation*Math.PI/180));b.X=a.X+unit.X*300;b.Y=a.Y+unit.Y*300;});var w=e.Connect(new(a.Id,"2"),new(b.Id,"1"),number:"SPECIAL",numberIndependent:true,color:"#AA0000",thickness:2.5,lineStyle:"dashed");var mid=new Point((a.X+b.X)/2,(a.Y+b.Y)/2);var c=e.InsertOnWire(w.Id,"terminal",mid,"1","2");var after=e.Sheet.Wires;assert(after.Count==2&&after.All(w=>w.Number=="SPECIAL"&&w.NumberIndependent&&w.Color=="#AA0000"&&w.Thickness==2.5&&w.LineStyle=="dashed"),"Style préservé "+rotation);assert(ProjectNavigation.Circuit(e.Project,after[0].Id).Count==2,"Passage raccordé "+rotation);assert((c.PortPoint("2")-c.PortPoint("1")).Length>0,"Ports distincts");}
        });
        test("Insertion : appareil sépare le numéro, bornes invalides refusées",()=>{
            var e=ParallelWires(1);string id=e.Sheet.Wires[0].Id;var c=e.InsertOnWire(id,"breaker1",new(200,350),"1","2");assert(e.Sheet.Wires.Select(w=>w.Number).Distinct().Count()==2,"Sortie appareil indépendante");var before=e.ExportSnapshot;reject(()=>e.InsertOnWire(id,"terminal",new(200,200),"1","1"));assert(e.ExportSnapshot==before,"Refus atomique");
        });
        test("Câbles : scission, suppression, gabarits remappés",()=>{
            var e=ParallelWires(1);var cable=e.MarkCableLine(new(160,350),new(240,350),"W1",1.5);var id=e.Sheet.Wires[0].Id;e.InsertOnWire(id,"terminal",new(200,450),"1","2");assert(e.Sheet.Wires.All(w=>w.CableId==cable.Id&&w.CableCore=="1"),"Même âme après scission");var clone=ProjectTemplates.Instantiate(e.Project,"Copie",true);assert(clone.Cables[0].Id!=cable.Id&&clone.Sheets[0].Wires.All(w=>w.CableId==clone.Cables[0].Id)&&clone.Sheets[0].CableMarkers[0].CableId==clone.Cables[0].Id,"Remappage câble");e.DeleteCable(cable.Id);assert(e.Sheet.Wires.Count==2&&e.Sheet.Wires.All(w=>w.CableId.Length==0),"Suppression sans fils perdus");e.Undo();assert(e.Project.Cables.Count==1,"Undo suppression");
        });
        test("Borniers : niveaux, pontages, graphique et tableau complet",()=>{
            var e=ParallelWires();var strip=e.InsertTerminalLine(new(160,300),new(540,300),"X1");var draft=DocumentModel.Copy(strip);draft.Terminals[1].Level=2;draft.Terminals[1].Number="1";draft.Bridges.Add(new(){FromComponent=draft.Terminals[0].ComponentId,ToComponent=draft.Terminals[2].ComponentId});e.PutTerminalStrip(draft);assert(e.Sheet.Components.Single(c=>c.Id==draft.Terminals[1].ComponentId).Tag=="X1:1","Texte numéro suit gestionnaire");var pages=e.GenerateTerminalPlan(strip.Id,"graphic");assert(pages.Count>=2&&pages.All(s=>s.TerminalPlanStyle=="graphic"),"Graphique plus tableau");var inks=Drawing.Scene(e.Project,pages[0]);assert(inks.Any(i=>i.Text=="Niv. 2")&&inks.Any(i=>i.Kind=="line"&&i.Color=="#087344"),"Niveaux et pont");Render(e,Path.Combine(dir,"self-test-terminal-graphic.png"));Export.Pdf(e.Project,Path.Combine(dir,"self-test-terminal-graphic.pdf"));var saved=e.ExportSnapshot;reject(()=>e.Change(()=>e.Sheet.TerminalMarkers.Add(new(){StripId=strip.Id,A=new(100,100),B=new(300,100)})));assert(e.ExportSnapshot==saved,"Plan généré protégé");
        });
        test("Routage : obstacles, maintien des extrémités et déplacement",()=>{
            var e=new Editor();var a=e.AddComponent("terminal",200,150);var b=e.AddComponent("terminal",200,650);e.AddComponent("coil",200,400);var w=e.Connect(new(a.Id,"2"),new(b.Id,"1"));string before=e.ExportSnapshot;e.RouteWires([w.Id]);var path=w.Route(e.Sheet);var router=new RoutingObstacles(e.Project,e.Sheet);assert(path.Count>2&&path[0]==a.PortPoint("2")&&path[^1]==b.PortPoint("1"),"Détour et bornes");for(int i=2;i<path.Count-1;i++)assert(router.Clear(path[i-1],path[i]),"Obstacle traversé");string after=e.ExportSnapshot;e.Undo();assert(e.ExportSnapshot==before,"Undo routage");e.Redo();assert(e.ExportSnapshot==after,"Redo routage");var component=e.Sheet.Components.Single(c=>c.Id==b.Id);e.Change(()=>component.X=550);assert(e.Sheet.Wires[0].RoutingWarning.Length==0&&e.Sheet.Wires[0].Route(e.Sheet)[^1]==component.PortPoint("1"),"Recalcul après déplacement");
        });
        test("Routage : sortie recouverte refusée sans mutation",()=>{
            var e=ParallelWires(1);e.AddComponent("coil",200,200);var before=e.ExportSnapshot;reject(()=>e.RouteWires([e.Sheet.Wires[0].Id]));assert(e.ExportSnapshot==before,"Route invalide atomique");
        });
        test("Blocs : câble, bornier et fils copiés, IDs et repères distincts",()=>{
            var e=ParallelWires();e.InsertTerminalLine(new(160,300),new(540,300),"X1");e.MarkCableLine(new(160,400),new(540,400),"W1",2.5);var block=CircuitBlocks.Extract(e.Project,e.Sheet,e.Sheet.Components.Select(c=>c.Id),"Quatre bornes","Borniers","puissance");string file=Path.Combine(dir,"self-test-circuit.gemblock");CircuitBlocks.Save(block,file);block=CircuitBlocks.Load(file);string before=e.ExportSnapshot;var ids=e.InsertBlock(block,new(750,100));assert(ids.Count==20&&e.Sheet.Components.Select(c=>c.Id).Distinct().Count()==24,"IDs nouveaux");assert(e.Project.Cables.Select(c=>c.Name).Distinct().Count()==2&&e.Project.TerminalStrips.Select(t=>t.Name).Distinct().Count()==2,"Repères indépendants");assert(e.Sheet.CableMarkers.Count==2&&e.Sheet.TerminalMarkers.Count==2,"Marquages copiés");string after=e.ExportSnapshot;e.Undo();assert(e.ExportSnapshot==before,"Une annulation");e.Redo();assert(e.ExportSnapshot==after,"Restauration exacte");reject(()=>e.InsertBlock(block,new(1300,700)));assert(e.ExportSnapshot==after,"Bloc hors cadre refusé");
        });
        test("Blocs : symbole privé et connexion externe détachée",()=>{
            var e=ParallelWires(1);var a=e.Sheet.Components[0];var definition=e.SaveSymbolCopy(CustomSymbols.Resolve(e.Project,"terminal"),a.Id);var block=CircuitBlocks.Extract(e.Project,e.Sheet,[a.Id],"Terminal privé");assert(block.DetachedConnections==1&&block.Project.Sheets[0].Wires.Count==0&&block.Project.CustomSymbols.Count==1,"Détachement et copie privée");var target=new Editor();target.InsertBlock(block,new(200,200));assert(target.Project.CustomSymbols.Count==1&&target.Sheet.Components[0].Symbol!=definition.Id,"Définition copiée");assert(!Symbols.All.ContainsKey(target.Sheet.Components[0].Symbol),"Originals intacts");
        });
        test("Favoris : stockage, catégorie, édition et invalidité atomique",()=>{
            string folder=Path.Combine(dir,"self-test-personal-"+Guid.NewGuid().ToString("N"));var entry=new PersonalEntry{Name="Ma borne",Category="Puissance",Tags="câble",BuiltinId="terminal"};PersonalLibrary.Save(entry,folder);assert(PersonalLibrary.List(folder).Single().Category=="Puissance","Persistance");entry.Tags="commande";PersonalLibrary.Save(entry,folder);assert(PersonalLibrary.List(folder).Single().Tags=="commande","Édition");entry.Category=new string('x',101);reject(()=>PersonalLibrary.Save(entry,folder));assert(PersonalLibrary.List(folder).Single().Category=="Puissance","Refus atomique");PersonalLibrary.Delete(entry.Id,folder);assert(PersonalLibrary.List(folder).Count==0,"Suppression locale");
        });
        test("Lecture : filtres, texte déplacé et exports inchangés",()=>{
            var e=ParallelWires(1);var c=e.Sheet.Components[0];e.Change(()=>{c.Rating="DETAIL-VIEW";e.Sheet.Notes.Add(new(){X=400,Y=300,Text="NOTE-VIEW"});});var canvas=new SheetCanvas(e);canvas.Measure(new(900,700));canvas.Arrange(new Rect(0,0,900,700));string before=e.ExportSnapshot;var scene=Drawing.Scene(e.Project,e.Sheet);canvas.SetReading(new(){TextScale=1.5,Details=false,Ports=false,WireNumbers=false,Notes=false});var reading=canvas.ReadingScene();assert(!reading.Any(i=>i.Text is "DETAIL-VIEW" or "NOTE-VIEW" or "P1"),"Filtres");assert(reading.Single(i=>i.Text==c.Tag).Size==scene.Single(i=>i.Text==c.Tag).Size*1.5,"Échelle écran");var ink=reading.Single(i=>i.Text==c.Tag);assert(canvas.BeginTextMove(new(ink.X+2,ink.Y+2)),"Hit texte affiché");canvas.CancelDrag();canvas.Select(c.Id);canvas.ZoomSelection();assert(canvas.Zoom>.6&&e.ExportSnapshot==before,"Cadrage sans mutation");assert(JsonSerializer.Serialize(Drawing.Scene(e.Project,e.Sheet))==JsonSerializer.Serialize(scene),"Exports stables");
        });
        test("Gestes : annulation entre les deux clics",()=>{
            var e=ParallelWires();var canvas=new SheetCanvas(e);string before=e.ExportSnapshot;canvas.SetMode("terminalLine");assert(canvas.BandClickForTest(new(150,300))&&e.InteractionInProgress,"Premier clic");canvas.SetMode("select");assert(!e.InteractionInProgress&&e.ExportSnapshot==before,"Échap annule");bool called=false;canvas.BandRequested+=(a,b,mode)=>{called=a==new Point(150,300)&&b==new Point(550,300)&&mode=="cableLine";};canvas.SetMode("cableLine");canvas.BandClickForTest(new(150,300));canvas.BandClickForTest(new(550,300));assert(called&&!e.InteractionInProgress,"Deux clics transmis");
        });
        test("Lecture : reports agrandis, destination séparée et saisie cohérente",()=>{
            var e=new Editor();var a=e.AddComponent("folio_next",200,200);var b=e.AddComponent("folio_previous",600,500);e.Change(()=>{a.LinkName=b.LinkName="REF-VIEW";});var canvas=new SheetCanvas(e);canvas.SetReading(new(){TextScale=2});var refs=new CrossReferences(e.Project);var name=canvas.Reading.TextInk(e.Project,a,refs,"tag")!;var detail=canvas.Reading.TextInk(e.Project,a,refs,"detail")!;assert(Drawing.TextBounds(name).Bottom<detail.Y,"Destination chevauche le nom agrandi");var point=Drawing.TextBounds(detail).TopLeft+new Vector(2,2);assert(canvas.BeginTextMove(point)&&canvas.Selected.Contains(a.Id),"Saisie du texte visible");canvas.CancelDrag();canvas.SetReading(new(){Details=false});assert(!canvas.BeginTextMove(point),"Destination masquée encore saisissable");
        });
        test("Projets : onglets, historique, vue et fermeture protégée",()=>{
            var window=new MainWindow();var first=window.Sessions[0];first.Editor.AddComponent("terminal",200,200);string firstState=first.Editor.ExportSnapshot;first.Canvas.Select(first.Editor.Sheet.Components[0].Id);first.Canvas.SetReading(new(){TextScale=1.5});var second=window.AddProjectTab(title:"Second");second.Editor.AddComponent("coil",400,400);window.WorkspaceCommandForTest("undo").Execute(null,window);assert(second.Editor.Sheet.Components.Count==0&&first.Editor.ExportSnapshot==firstState,"Historique actif distinct");window.SelectProjectTab(first.Id);assert(window.Canvas.Selected.Count==1&&window.Canvas.Reading.TextScale==1.5,"Vue conservée");reject(()=>window.CloseProjectTab(first.Id));assert(window.Sessions.Count==2,"Fermeture dirty refusée");string file=Path.Combine(dir,"self-test-tab.gemelec");first.Editor.Save(file);window.AddProjectTab(path:file);assert(window.Sessions.Count==2,"Fichier déjà ouvert activé");window.CloseProjectTab(first.Id);assert(window.ActiveSessionId==second.Id,"Autre onglet actif");second.Editor.Save(Path.Combine(dir,"self-test-tab-second.gemelec"));
        });
        test("Migration : version 7 conserve le PDF et adopte les câbles",()=>{
            var p=new Project();p.PdfOptions.Contents=true;string old=ProjectStore.Serialize(p).Replace($"\"version\":{Project.CurrentVersion}","\"version\":7");var loaded=ProjectStore.Deserialize(old);assert(loaded.Version==Project.CurrentVersion&&loaded.PdfOptions.Contents&&loaded.Cables.Count==0,"Migration 7");
        });
        test("Interface : gestionnaires et gestes accessibles hors écran",()=>{
            var window=new MainWindow();int dialogs=0;try{window.Editor.ImportProject(ParallelWires().Project);window.DocumentTestProbe=dialog=>{dialogs++;var root=(FrameworkElement)dialog.Content;root.Measure(new(1050,700));root.Arrange(new(0,0,1050,700));root.UpdateLayout();var image=new RenderTargetBitmap(1050,700,96,96,PixelFormats.Pbgra32);image.Render(root);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(image));using var file=File.Create(Path.Combine(dir,"self-test-new-dialog-"+dialogs+".png"));png.Save(file);};
                foreach(string command in new[]{"cables","personalLibrary","reading"})window.WorkspaceCommandForTest(command).Execute(null,window);
                window.Canvas.Select(window.Editor.Sheet.Wires[0].Id);window.WorkspaceCommandForTest("insertOnWire").Execute(null,window);
                foreach(string mode in new[]{"terminalLine","cableLine"}){window.Canvas.SetMode(mode);window.Canvas.BandClickForTest(new(160,350));window.Canvas.BandClickForTest(new(540,350));}assert(dialogs==6,"Gestionnaire inaccessible");
                window.AddProjectTab(title:"Autre projet");var content=(FrameworkElement)window.Content;content.Measure(new(1440,900));content.Arrange(new(0,0,1440,900));content.UpdateLayout();var bitmap=new RenderTargetBitmap(1440,900,96,96,PixelFormats.Pbgra32);bitmap.Render(content);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using var output=File.Create(Path.Combine(dir,"self-test-project-tabs.png"));encoder.Save(output);
            }finally{window.DocumentTestProbe=null;window.DisposeTestBridge();}
        });
        test("Borniers : pagination de treize positions et cinq niveaux",()=>{
            var e=new Editor();var strip=new TerminalStrip{Name="X-GRAND"};e.Change(()=>{for(int level=1;level<=5;level++)for(int number=1;number<=13;number++){var c=new Component{Symbol="terminal",X=100+number*80,Y=100+level*100,Tag="X"+level+"_"+number};e.Sheet.Components.Add(c);strip.Terminals.Add(new(){ComponentId=c.Id,Number=number.ToString(),Level=level,Comment="Commentaire entier du raccordement "+number});}e.Project.TerminalStrips.Add(strip);});var pages=e.GenerateTerminalPlan(strip.Id,"graphic");assert(TerminalGraphics.PageCount(strip)==4&&pages.Count>4,"Pagination positions/niveaux");var all=pages.SelectMany(s=>Drawing.Scene(e.Project,s)).ToList();assert(all.Any(i=>i.Text=="Niv. 5")&&all.Any(i=>i.Text.Contains("Commentaire entier du raccordement 13")),"Détails et niveau 5 conservés");ProjectStore.Deserialize(e.ExportSnapshot);Render(e,Path.Combine(dir,"self-test-terminal-large.png"));
        });
        test("Projets : refuser un enregistrement sur le fichier d’un autre onglet",()=>{
            var window=new MainWindow();try{var first=window.Sessions[0];string path=Path.Combine(dir,"self-test-tab-protected.gemelec");first.Editor.Save(path);window.AddProjectTab(title:"Copie");reject(()=>window.CheckProjectSavePath(path));assert(window.Sessions.Count==2&&!first.Editor.Dirty,"Autre onglet conservé");}finally{window.DisposeTestBridge();}
        });
        test("Routage : mesure sur un folio dense",()=>{
            var e=ParallelWires(4);e.Change(()=>{for(int row=0;row<12;row++)for(int col=0;col<8;col++)e.Sheet.Components.Add(new(){Symbol="terminal",Tag="DENSE"+row+"_"+col,X=600+col*80,Y=100+row*55});});var timer=Stopwatch.StartNew();e.RouteWires(e.Sheet.Wires.Select(w=>w.Id));timer.Stop();File.WriteAllText(Path.Combine(dir,"self-test-routing-measure.json"),JsonSerializer.Serialize(new{components=e.Sheet.Components.Count,wires=e.Sheet.Wires.Count,milliseconds=timer.ElapsedMilliseconds}));assert(timer.ElapsedMilliseconds<15000,"Routage dense supérieur à 15 secondes");
        });
    }
}
